using System.Security.Claims;
using HeroStory.Api.DTOs.Scene;
using HeroStory.Api.Services;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;
namespace HeroStory.Api.Controllers; [ApiController][Authorize][Route("api/sessions/{id:guid}/scenes")] public class ScenesController : ControllerBase { private readonly ISceneService _sceneService; public ScenesController(ISceneService sceneService) { _sceneService = sceneService; } [HttpGet] public Task<IReadOnlyList<SceneListDto>> GetScenes(Guid id, CancellationToken cancellationToken) => _sceneService.GetScenesAsync(GetUserId(), id, cancellationToken); [HttpPost][EnableRateLimiting("scenes")] public async Task<ActionResult<SceneDto>> CreateScene(Guid id, CreateSceneRequest request, CancellationToken cancellationToken) { var response = await _sceneService.CreateSceneAsync(GetUserId(), id, request, cancellationToken); return CreatedAtAction(nameof(GetScene), new { id, sceneId = response.Id }, response); } [HttpPost("{sceneId:guid}/artwork")][EnableRateLimiting("scenes")] public async Task<ActionResult<SceneDto>> RequestArtwork(Guid id, Guid sceneId, CancellationToken cancellationToken) { var response = await _sceneService.RequestArtworkAsync(GetUserId(), id, sceneId, cancellationToken); return AcceptedAtAction(nameof(GetScene), new { id, sceneId = response.Id }, response); } [HttpPost("{sceneId:guid}/revisions")][EnableRateLimiting("scenes")] public async Task<ActionResult<SceneDto>> ReviseScene(Guid id, Guid sceneId, ReviseSceneRequest request, CancellationToken cancellationToken) { var response = await _sceneService.ReviseLatestSceneAsync(GetUserId(), id, sceneId, request, cancellationToken); return CreatedAtAction(nameof(GetScene), new { id, sceneId = response.Id }, response); } [HttpGet("{sceneId:guid}")] public async Task<ActionResult<SceneDto>> GetScene(Guid id, Guid sceneId, CancellationToken cancellationToken) { var response = await _sceneService.GetSceneAsync(GetUserId(), id, sceneId, cancellationToken); return response is null ? NotFound() : Ok(response); } private Guid GetUserId() => Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier) ?? throw new UnauthorizedAccessException()); }
